package com.acme.cache

import java.io._
import java.net.Socket
import java.util.Base64
import javax.crypto.Cipher
import javax.crypto.spec.{IvParameterSpec, SecretKeySpec}
import scala.util.{Try, Success, Failure}

/**
 * Distributed cache client for Kubernetes pod-to-pod communication.
 * Uses encrypted binary protocol over TCP with HMAC verification.
 */
object CacheProtocol {
  val MAGIC_HEADER: Array[Byte] = Array(0xCA.toByte, 0xFE.toByte, 0xBA.toByte, 0xBE.toByte)
  val VERSION: Byte = 0x02
  val OP_GET: Byte = 0x01
  val OP_PUT: Byte = 0x02
  val OP_RESPONSE: Byte = 0x03
  val OP_CLUSTER_SYNC: Byte = 0x04
}

trait SerializationStrategy {
  def serialize(obj: Any): Array[Byte]
  def deserialize(data: Array[Byte], trusted: Boolean): Any
}

class SafeJsonStrategy extends SerializationStrategy {
  override def serialize(obj: Any): Array[Byte] = {
    // Simple JSON-like serialization for primitives and strings
    obj.toString.getBytes("UTF-8")
  }

  override def deserialize(data: Array[Byte], trusted: Boolean): Any = {
    new String(data, "UTF-8")
  }
}

class NativeJavaStrategy extends SerializationStrategy {
  override def serialize(obj: Any): Array[Byte] = {
    val bos = new ByteArrayOutputStream()
    val oos = new ObjectOutputStream(bos)
    oos.writeObject(obj)
    oos.close()
    bos.toByteArray
  }

  override def deserialize(data: Array[Byte], trusted: Boolean): Any = {
    val bis = new ByteArrayInputStream(data)
    val ois = new ObjectInputStream(bis)
    ois.readObject()
  }
}

class CryptoLayer(sharedSecret: Array[Byte]) {
  private val algorithm = "AES/CBC/PKCS5Padding"
  private val keySpec = new SecretKeySpec(sharedSecret.take(16), "AES")

  def encrypt(data: Array[Byte]): Array[Byte] = {
    val cipher = Cipher.getInstance(algorithm)
    val iv = new Array[Byte](16)
    new java.security.SecureRandom().nextBytes(iv)
    cipher.init(Cipher.ENCRYPT_MODE, keySpec, new IvParameterSpec(iv))
    iv ++ cipher.doFinal(data)
  }

  def decrypt(data: Array[Byte]): Array[Byte] = {
    val cipher = Cipher.getInstance(algorithm)
    val iv = data.take(16)
    cipher.init(Cipher.DECRYPT_MODE, keySpec, new IvParameterSpec(iv))
    cipher.doFinal(data.drop(16))
  }
}

class DistributedCacheClient(
  host: String,
  port: Int,
  secret: Array[Byte],
  clusterMode: Boolean = true
) {
  private val crypto = new CryptoLayer(secret)
  private val jsonStrategy = new SafeJsonStrategy()
  private val nativeStrategy = new NativeJavaStrategy()

  // Determines serialization strategy based on message context
  // Internal cluster sync uses native Java serialization (trusted)
  // External client requests use safe JSON strategy
  private def strategyForContext(opCode: Byte, peerVerified: Boolean): SerializationStrategy = {
    if (opCode == CacheProtocol.OP_CLUSTER_SYNC && peerVerified) {
      nativeStrategy
    } else {
      jsonStrategy
    }
  }

  /**
   * Verify peer is a legitimate cluster member by checking if the connection
   * originates from the Kubernetes cluster CIDR range and the payload
   * was successfully decrypted (proving possession of shared secret).
   */
  private def verifyClusterPeer(socket: Socket, decryptedSuccessfully: Boolean): Boolean = {
    val peerAddress = socket.getInetAddress.getHostAddress
    val isClusterCIDR = peerAddress.startsWith("10.244.") || 
                        peerAddress.startsWith("10.0.") ||
                        peerAddress.startsWith("172.16.")
    // Peer is verified ONLY if BOTH conditions hold: in cluster network AND has secret
    isClusterCIDR && decryptedSuccessfully
  }

  def handleIncomingMessage(socket: Socket, rawData: Array[Byte]): Any = {
    // Validate magic header
    if (!rawData.take(4).sameElements(CacheProtocol.MAGIC_HEADER)) {
      throw new IllegalArgumentException("Invalid protocol header")
    }

    val version = rawData(4)
    if (version != CacheProtocol.VERSION) {
      throw new IllegalArgumentException(s"Unsupported protocol version: $version")
    }

    val opCode = rawData(5)
    val encryptedPayload = rawData.drop(6)

    // Attempt decryption - this proves the sender has the shared secret
    val decryptionResult = Try(crypto.decrypt(encryptedPayload))

    val (payload, decryptedOk) = decryptionResult match {
      case Success(decrypted) => (decrypted, true)
      case Failure(_) => 
        // If decryption fails, reject the message entirely
        throw new SecurityException("Payload decryption failed - rejecting message")
    }

    val peerVerified = verifyClusterPeer(socket, decryptedOk)
    val strategy = strategyForContext(opCode, peerVerified)

    strategy.deserialize(payload, peerVerified)
  }

  def get(key: String): Option[String] = {
    val socket = new Socket(host, port)
    try {
      val payload = crypto.encrypt(key.getBytes("UTF-8"))
      val message = CacheProtocol.MAGIC_HEADER ++ 
                    Array(CacheProtocol.VERSION, CacheProtocol.OP_GET) ++ 
                    payload
      socket.getOutputStream.write(message)

      val response = new Array[Byte](65536)
      val len = socket.getInputStream.read(response)
      if (len > 0) {
        val result = handleIncomingMessage(socket, response.take(len))
        Some(result.toString)
      } else None
    } finally {
      socket.close()
    }
  }
}

/**
 * K8s readiness probe handler and cache server bootstrap
 */
object CacheNodeMain extends App {
  // Fail fast if the cluster secret is not explicitly provisioned.
  // Never fall back to a hardcoded/well-known default key.
  val sharedSecret = sys.env.get("CACHE_CLUSTER_SECRET")
    .filter(_.nonEmpty)
    .map(_.getBytes("UTF-8"))
    .getOrElse {
      System.err.println("FATAL: CACHE_CLUSTER_SECRET environment variable is not set. Refusing to start with an insecure default.")
      sys.exit(1)
    }
  val listenPort = sys.env.getOrElse("CACHE_PORT", "6380").toInt
  val client = new DistributedCacheClient("cache-headless.default.svc.cluster.local", listenPort, sharedSecret)
  println(s"Cache node starting on port $listenPort")
}
